req = urllib.request.Request(result_url, headers={
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    "Referer": "https://mops.twse.com.tw/mops/"
})

resp = urllib.request.urlopen(req)
raw = resp.read()

for enc in ["cp950", "big5", "utf-8", "gbk"]:
    try:
        t = raw.decode(enc)
        if "公司" in t or "損益" in t or "營業" in t or "高鐵" in t:
            print("Successfully decoded with:", enc)
            for line in t.splitlines():
                if "2633" in line or "高鐵" in line or "th class" in line or "公司" in line:
                    print(line)
            break
    except Exception as e:
        # print(enc, e)
        pass
"

